sysauto_script.script:
//Festlegen von Konstanten für die System Properties aus dem System Property Catalog CSV Properties
BUSL_AGENCY = gs.getProperty('x_sigh_a_a_portal.busl_for_agency','default value');
BUSL_TAXOFFICE = gs.getProperty('x_sigh_a_a_portal.busl_for_tax_office','default value');
ADDITIONAL_INFORMATION_TYPE = gs.getProperty('x_sigh_a_a_portal.additional_information_type','default value');
ADDITIONAL_INFORMATION_TEXT = gs.getProperty('x_sigh_a_a_portal.additional_information_text','default value');
VAT = 19;

function calculateNetPrice(priceWithVAT) {
    return priceWithVAT / (1 + VAT / 100);
}

function calculateVAT(priceWithVAT,netPrice) {
    return (priceWithVAT - netPrice);
}

function getAdditionalInformation(){
	var additional_information = '';
	var current_date = new Date();
	switch(ADDITIONAL_INFORMATION_TYPE){
		case 'Month':
			var months = ["Januar", "Februar", "März", "April", "Mai", "Juni", 
                		  "Juli", "August", "September", "Oktober", "November", "Dezember"];
			additional_information = ADDITIONAL_INFORMATION_TEXT+ ' '+ months[current_date.getMonth()];
			break;
	}

	return additional_information;
}


//BOM \uFEFF für UTF-8 wird verwendet um bspw. Excel mitzuteilen die CSV-Datei UTF-8 codiert zu interpretieren(bspw. für das € - Symbol)
var csvString = "\uFEFF";
var csvHeader = ["Agency","BUSL","Zusatztext","Produkt","Preis"];
var csvBody = "";
var data = {};
var grAgentComps = new GlideRecord('core_company');
grAgentComps.addNotNullQuery('parent'); // Agencies sind Companies, bei denen der parent nicht leer ist
grAgentComps.orderBy('name');
grAgentComps.query();

csvString += csvHeader.join(';') + '\r\n';  //Aufbau des Headers für das CSV

//Agencies werden in einer Schleife durchlaufen
while(grAgentComps.next()){
	var buslArr = [BUSL_AGENCY,BUSL_TAXOFFICE];
	var vatNetPriceSwitch = true;

		var companyName = grAgentComps.getValue('name');
		var gaAsset = new GlideRecord('alm_asset');
		gaAsset.addQuery('company',grAgentComps.getValue('sys_id'));	
		gaAsset.query();
		//Assets die zu den Agencies gehören, werden  in einer Schleife durchlaufen
		while(gaAsset.next()){
			buslArr.forEach(function(busl) {
				var tempAssetArr = [];
				var priceWithVAT = parseFloat(Number(gaAsset.getValue('cost')));
				var netPrice = calculateNetPrice(priceWithVAT).toFixed(2);
				var vat = calculateVAT(priceWithVAT,netPrice).toFixed(2);
				var product = gaAsset.getValue('display_name');
				var additional_information = getAdditionalInformation();

				tempAssetArr.push('"'+companyName+'"');
				tempAssetArr.push('"'+busl+'"');
				tempAssetArr.push('"'+additional_information+'"');
				tempAssetArr.push('"'+product+'"');

				if(vatNetPriceSwitch){
					tempAssetArr.push('"'+ netPrice.replace(".",",") +' €"');
					vatNetPriceSwitch = false;
				}
				else{
					tempAssetArr.push('"'+ vat.replace(".",",") +' €"');
					vatNetPriceSwitch = true;
				}

				csvBody += tempAssetArr.join(";") + "\r\n"; //Aufbau des Body für das CSV
			});
		}
}

//Zusammenfügen des Headers und des Body 
csvString += csvBody;

//Erzeugung eines GlideSysAttachment-Objekts
var grAttachment = new GlideSysAttachment();
var grRec  = new GlideRecord('sys_attachment');

//Abspeichern der CSV in der sys_attachment-Tabelle
grAttachment.write(grRec,'AssetTest01.csv','application/csv',csvString);
gs.info('CSV-Datei wurde erfolgreich erstellt');
